import { readFileSync } from "node:fs";
import yaml from "js-yaml";

const file = process.argv[2];
const spec = yaml.load(readFileSync(file, "utf8"));
const version = spec.openapi ?? spec.swagger;
const ok = typeof version === "string" && (/^3\.[0-2]\.\d+$/.test(version) || version === "2.0");

if (!ok) {
  console.error(`${file}: version field is ${typeof version} ${JSON.stringify(version)}`);
  process.exit(1);
}
console.log(`${file}: ${version} ok`);
